class ShadowMeshHeader:
    face_offset: int
    vertex_offset: int
    edge_offset: int
    face_count: int
    vertex_count: int
    edge_count: int
    bone_index: int

    @classmethod
    def from_buffer(cls, buffer: Buffer):
        try:
            return cls(*buffer.read_fmt("7I"))
        except:
            data = buffer.read_fmt("6I")
            return cls(data[0], data[1], data[2], data[3], data[4], data[5], 0)

