class MefModelIGI2:
    def __init__(self, buffer: Buffer, export_mode: str = "simple", debug_params: Optional[MefDebugParams] = None):
        self.debug_params = debug_params or MefDebugParams()
        loop_file = LoopFile(buffer, flip_ident=True)
